CREATE COLUMN TABLE "TEST_AP"."NFN3" ("ObjectCode" NVARCHAR(20) NOT NULL , "SeqCode" SMALLINT CS_INT DEFAULT 0 NOT NULL , "DocSubType" NVARCHAR(2) DEFAULT '--' NOT NULL , PRIMARY KEY ("ObjectCode", "DocSubType", "SeqCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
